// Harness entry — the only script index.html loads. Not app code.
// 1. Install the Trusted Types boundary before anything else can touch the DOM.
// 2. Start the app.
import './trusted-boundary';
import '../src/main';
/**
 * The single trusted boundary — the only place a raw HTML string is allowed in.
 *
 * With `require-trusted-types-for 'script'` in the CSP, a string reaching a DOM sink is routed
 * through the policy named `default` if one exists, and refused otherwise. This policy sanitizes.
 * It is small on purpose: the whole trusted surface of the app is this file, and it is reviewed,
 * exempted by name in tsec-exemptions.json, and untouchable by the agent (verify.sh gate 0).
 */
import DOMPurify from 'dompurify';

const ALLOWED_TAGS = ['a', 'b', 'strong', 'i', 'em', 'u', 's', 'br', 'p', 'span', 'code', 'pre', 'ul', 'ol', 'li', 'blockquote'];
const ALLOWED_ATTR = ['href', 'title', 'target', 'rel'];

function sanitize(html: string): string {
  return DOMPurify.sanitize(html, { ALLOWED_TAGS, ALLOWED_ATTR, ALLOW_DATA_ATTR: false, KEEP_CONTENT: true });
}

/** Best-effort telemetry: the server logs it under runs/ (a test signal and a demo overlay). */
function report(sink: string, sample: string): void {
  try {
    navigator.sendBeacon('/tt-report', JSON.stringify({ sink, sample: sample.slice(0, 300), href: location.href }));
  } catch {
    /* reporting never affects the app */
  }
}

if (window.trustedTypes) {
  window.trustedTypes.createPolicy('default', {
    createHTML: (s: string): string => {
      const clean = sanitize(s);
      if (clean !== s) report('html', s);
      return clean;
    },
    createScriptURL: (s: string): string => {
      report('script-url', s);
      throw new TypeError('Trusted Types: script URLs from strings are not allowed here');
    },
    createScript: (s: string): string => {
      report('script', s);
      throw new TypeError('Trusted Types: dynamic script from strings is not allowed here');
    },
  });
}
// Build config for arm B. Part of the harness (verify.sh gate 0 checks it is untouched).
import path from 'node:path';
import { defineConfig } from 'vite';

const root = path.resolve(import.meta.dirname, '..');

export default defineConfig({
  root,
  publicDir: path.join(root, 'public'),
  build: {
    outDir: path.join(root, 'dist'),
    emptyOutDir: true,
    target: 'es2022',
    // One nonce'd module script, no preload hints: exactly what a strict CSP with 'strict-dynamic' expects.
    modulePreload: false,
    sourcemap: false,
    rollupOptions: { output: { inlineDynamicImports: true } },
  },
  plugins: [harnessGuard()],
});

/**
 * Refuses at build time what the CSP would refuse at runtime, so the feedback arrives in the loop:
 * inline scripts, inline event handlers, javascript: URLs, and an index.html that skips the harness entry.
 */
function harnessGuard() {
  return {
    name: 'harness-guard',
    enforce: 'pre',
    transformIndexHtml: {
      order: 'pre',
      handler(html) {
        const problems = [];
        if (!/<script\b[^>]*\ssrc=["']\/harness\/entry\.ts["'][^>]*>/i.test(html)) {
          problems.push(
            'index.html must load the harness entry exactly like this: <script type="module" src="/harness/entry.ts"></script> — it installs the Trusted Types boundary before src/main.ts runs.',
          );
        }
        const inline = html.match(/<script\b(?![^>]*\ssrc=)[^>]*>[\s\S]*?<\/script>/gi) ?? [];
        if (inline.length) problems.push(`inline <script> blocks are blocked by the strict CSP (${inline.length} found). Move the code into src/.`);
        const handlers = html.match(/\son[a-z]+\s*=\s*["']/gi) ?? [];
        if (handlers.length) problems.push(`inline event handler attributes are blocked by the strict CSP (${handlers.map((h) => h.trim()).join(', ')}). Use addEventListener in src/.`);
        if (/javascript:/i.test(html)) problems.push('javascript: URLs are blocked by the strict CSP.');
        if (problems.length) throw new Error('harness-guard: index.html is not CSP-compatible\n - ' + problems.join('\n - '));
        return html;
      },
    },
  };
}
