1	import type { Page } from '@playwright/test';
2	import { SEL } from './contract.ts';
3	import type { Payload } from './payloads.ts';
4	
5	declare global {
6	  interface Window {
7	    __xss: string | null;
8	    __csp: string[];
9	  }
10	}
11	
12	export interface PageProbe {
13	  dialogs: number;
14	  pageErrors: string[];
15	}
16	
17	/**
18	 * Arms a fresh page for the benchmark:
19	 *  - no network: only the arm's own server is reachable (a payload's success is unambiguous)
20	 *  - window.__xss sentinel + CSP violation listener installed before any app code runs
21	 *  - dialogs are dismissed and counted
22	 */
23	export async function armPage(page: Page): Promise<PageProbe> {
24	  const probe: PageProbe = { dialogs: 0, pageErrors: [] };
25	  await page.route('**/*', (route) => {
26	    const host = new URL(route.request().url()).hostname;
27	    if (host === '127.0.0.1' || host === 'localhost') return route.continue();
28	    return route.abort('blockedbyclient');
29	  });
30	  await page.addInitScript(() => {
31	    window.__xss = null;
32	    window.__csp = [];
33	    document.addEventListener('securitypolicyviolation', (e) => {
34	      window.__csp.push(`${e.violatedDirective}${e.sample ? ' ' + e.sample.slice(0, 80) : ''}`);
35	    });
36	  });
37	  page.on('dialog', (d) => {
38	    probe.dialogs += 1;
39	    void d.dismiss();
40	  });
41	  page.on('pageerror', (e) => probe.pageErrors.push(String(e.message ?? e)));
42	  return probe;
43	}
44	
45	export async function openApp(page: Page, hash = ''): Promise<void> {
46	  await page.goto('/' + hash);
47	  await waitForApp(page);
48	}
49	
50	export async function waitForApp(page: Page): Promise<void> {
51	  await page.locator(SEL.feed).waitFor({ state: 'attached', timeout: 10_000 });
52	  await page.locator(SEL.form).waitFor({ state: 'attached', timeout: 10_000 });
53	}
54	
55	export interface NoteInput {
56	  title: string;
57	  body: string;
58	  avatar?: string;
59	}
60	
61	export async function addNote(page: Page, note: NoteInput): Promise<void> {
62	  await page.fill(SEL.title, note.title);
63	  await page.fill(SEL.body, note.body);
64	  await page.fill(SEL.avatar, note.avatar ?? '');
65	  await page.locator(SEL.submit).first().click();
66	}
67	
68	export async function settle(page: Page, ms = 700): Promise<void> {
69	  await page.waitForTimeout(ms);
70	}
71	
72	export async function xssFired(page: Page): Promise<string | null> {
73	  return page.evaluate(() => window.__xss);
74	}
75	
76	export async function cspViolations(page: Page): Promise<string[]> {
77	  return page.evaluate(() => window.__csp ?? []);
78	}
79	
80	/**
81	 * Clicks every javascript: link the app rendered (stored js-URI XSS needs a click).
82	 * A javascript: navigation whose script returns a string replaces the document with that string,
83	 * so "the app is gone and the page is just the payload's result" also counts as execution.
84	 */
85	async function clickJavascriptLinks(page: Page): Promise<{ links: number; executed: boolean }> {
86	  const links = page.locator(`${SEL.feed} a[href^="javascript:" i]`);
87	  const n = await links.count();
88	  let executed = false;
89	  for (let i = 0; i < n && !executed; i++) {
90	    try {
91	      await links.nth(i).click({ noWaitAfter: true, force: true, timeout: 2_000 });
92	    } catch {
93	      /* hidden / detached — nothing to click */
94	    }
95	    await settle(page, 300);
96	    executed = await page.evaluate(() => {
97	      if (window.__xss !== null && window.__xss !== undefined) return true;
98	      const text = (document.body?.textContent ?? '').trim();
99	      return document.querySelector('#feed') === null && text.length > 0 && text.length < 200;
100	    });
101	  }
102	  return { links: n, executed };
103	}
104	
105	export interface PayloadResult {
106	  id: string;
107	  field: Payload['field'];
108	  fired: boolean;
109	  how: string | null; // which observation caught it
110	  firedImmediately: boolean;
111	  firedOnClick: boolean;
112	  firedAfterReload: boolean;
113	  javascriptLinksRendered: number;
114	  javascriptAvatarRendered: boolean;
115	  csp: string[];
116	  pageErrors: string[];
117	  dialogs: number;
118	}
119	
120	/**
121	 * Drives one payload through the app exactly as a user (or attacker) would:
122	 * submit it through its field, or navigate to the fragment; then observe immediately,
123	 * after clicking any javascript: links, and again after a reload (stored XSS).
124	 */
125	export async function drivePayload(page: Page, probe: PageProbe, p: Payload): Promise<PayloadResult> {
126	  switch (p.field) {
127	    case 'body':
128	    case 'title':
129	    case 'avatar': {
130	      await openApp(page);
131	      const note: NoteInput = { title: 'benchmark note', body: 'benchmark body', avatar: '' };
132	      note[p.field] = p.value;
133	      await addNote(page, note);
134	      break;
135	    }
136	    case 'search': {
137	      await openApp(page);
138	      await page.fill(SEL.search, p.value);
139	      break;
140	    }
141	    case 'hash': {
142	      // The app writes the fragment with URLSearchParams-style encoding; navigate the same way.
143	      const q = p.value.replace(/^#q=/, '');
144	      await openApp(page, '#q=' + encodeURIComponent(q));
145	      break;
146	    }
147	  }
148	  await settle(page);
149	  const firedImmediately = (await xssFired(page)) !== null;
150	
151	  const clicked = await clickJavascriptLinks(page);
152	  const jsLinks = clicked.links;
153	  const firedOnClick = !firedImmediately && clicked.executed;
154	
155	  const javascriptAvatarRendered =
156	    (await page.locator(`${SEL.feed} ${SEL.noteAvatar}[src^="javascript:" i]`).count()) > 0;
157	
158	  await page.reload();
159	  await waitForApp(page).catch(() => undefined);
160	  await settle(page);
161	  let firedAfterReload = (await xssFired(page)) !== null;
162	  if (!firedAfterReload) firedAfterReload = (await clickJavascriptLinks(page)).executed;
163	
164	  const fired = firedImmediately || firedOnClick || firedAfterReload;
165	  const how = firedImmediately
166	    ? 'executed on submit/navigation'
167	    : firedOnClick
168	      ? 'executed when the rendered javascript: link was clicked'
169	      : firedAfterReload
170	        ? 'executed when the stored note was re-rendered after reload'
171	        : null;
172	
173	  return {
174	    id: p.id,
175	    field: p.field,
176	    fired,
177	    how,
178	    firedImmediately,
179	    firedOnClick,
180	    firedAfterReload,
181	    javascriptLinksRendered: jsLinks,
182	    javascriptAvatarRendered,
183	    csp: await cspViolations(page),
184	    pageErrors: probe.pageErrors.slice(),
185	    dialogs: probe.dialogs,
186	  };
187	}
