import path from 'node:path';

export type ArmId = 'a' | 'b';

export interface Arm {
  id: ArmId;
  label: string;
  pkg: string;          // pnpm workspace package name
  dir: string;          // absolute path
  port: number;
  serveScript: string;  // relative to dir
  // Agent-written files the static scan looks at (relative to dir).
  scanGlobs: string[];
}

export const ROOT = path.resolve(import.meta.dirname, '..');
// RUNS_DIR redirects every benchmark output (security jsonl, Playwright reports, scorecards) — used by side experiments.
export const RUNS = process.env.RUNS_DIR ? path.resolve(process.env.RUNS_DIR) : path.join(ROOT, 'runs');
// PORT_BASE lets several copies of the repo (matrix lanes) benchmark side by side without port clashes.
const PORT_BASE = Number(process.env.PORT_BASE ?? 4173);

export const ARMS: Record<ArmId, Arm> = {
  a: {
    id: 'a',
    label: 'Arm A — vibe (no guardrails)',
    pkg: 'arm-a-vibe',
    dir: path.join(ROOT, 'arm-a-vibe'),
    port: PORT_BASE,
    serveScript: 'server.mjs',
    scanGlobs: ['src/**/*.{ts,js,mts,mjs}', 'index.html'],
  },
  b: {
    id: 'b',
    label: 'Arm B — high-assurance harness',
    pkg: 'arm-b-harness',
    dir: path.join(ROOT, 'arm-b-harness'),
    port: PORT_BASE + 1,
    serveScript: 'harness/server.mjs',
    scanGlobs: ['src/**/*.{ts,js,mts,mjs}', 'index.html'],
  },
};

export function armFromEnv(): Arm {
  const id = (process.env.ARM ?? 'a') as ArmId;
  const arm = ARMS[id];
  if (!arm) throw new Error(`Unknown ARM=${process.env.ARM}; expected "a" or "b"`);
  return arm;
}

import { defineConfig } from '@playwright/test';
import path from 'node:path';
import { armFromEnv, RUNS } from './arms.ts';

// One config for both arms. ARM=a|b selects the app under test; everything else is identical.
const arm = armFromEnv();
const out = path.join(RUNS, `pw-${arm.id}`);
// verify.sh runs the two spec files separately; keep their JSON reports apart so neither overwrites the other.
const argvSpecs = process.argv.slice(2).filter((a) => /\.spec\.ts$/.test(a)).map((a) => path.basename(a, '.spec.ts'));
const reportName = argvSpecs.length === 1 ? `results-${argvSpecs[0]}.json` : 'results.json';

export default defineConfig({
  testDir: import.meta.dirname,
  testMatch: /(security|functional|bypass)\.spec\.ts$/,
  workers: 1,
  fullyParallel: false,
  retries: 0,
  timeout: 30_000,
  expect: { timeout: 5_000 },
  outputDir: path.join(out, 'test-results'),
  reporter: [['list'], ['json', { outputFile: path.join(out, reportName) }]],
  use: {
    baseURL: `http://127.0.0.1:${arm.port}`,
    browserName: 'chromium',
    video: 'on',
    trace: 'on',
    viewport: { width: 1280, height: 720 },
  },
  webServer: {
    command: `node ${arm.serveScript} --port ${arm.port}`,
    cwd: arm.dir,
    url: `http://127.0.0.1:${arm.port}/`,
    reuseExistingServer: false,
    timeout: 20_000,
    env: { CSP_REPORT_LOG: path.join(RUNS, `arm-${arm.id}-csp-reports.jsonl`) },
  },
});

