:root {
  --bg: #f5f5f4;
  --surface: #ffffff;
  --ink: #1c1917;
  --muted: #57534e;
  --line: #d6d3d1;
  --accent: #0f766e;
  --radius: 10px;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1c1917;
    --surface: #292524;
    --ink: #f5f5f4;
    --muted: #a8a29e;
    --line: #44403c;
    --accent: #5eead4;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  max-width: 44rem;
  margin: 0 auto;
  padding: 2rem 1rem 4rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: -0.01em;
}

.tagline {
  margin: 0.25rem 0 0;
  color: var(--muted);
}

.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.25rem;
}

.card h2 {
  margin: 0 0 1rem;
  font-size: 1.1rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  font: inherit;
  color: inherit;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0.5rem 0.65rem;
  width: 100%;
}

textarea {
  resize: vertical;
}

.hint {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
}

.hint code {
  font-size: 0.95em;
}

button {
  font: inherit;
  font-weight: 600;
  color: var(--bg);
  background: var(--accent);
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 0.5rem 1rem;
  cursor: pointer;
}

button:hover {
  filter: brightness(1.08);
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.search-field {
  margin-bottom: 0;
}

.results-line {
  margin: 0;
  min-height: 1.4em;
  font-size: 0.9rem;
  color: var(--muted);
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 4px solid transparent;
  border-radius: var(--radius);
  padding: 1rem 1.25rem;
}

.note[aria-current="true"] {
  border-left-color: var(--accent);
  box-shadow: 0 1px 12px rgb(0 0 0 / 0.08);
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.note-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--line);
  flex: none;
}

.note-heading {
  margin: 0;
  font-size: 1.05rem;
}

/* The title is the control that selects a note; it should still read as a heading. */
.note-title {
  font: inherit;
  font-weight: 700;
  color: var(--ink);
  background: none;
  border: none;
  border-radius: 4px;
  padding: 0;
  text-align: left;
  cursor: pointer;
}

.note-title:hover {
  color: var(--accent);
  filter: none;
}

.note-body {
  margin-top: 0.5rem;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--accent);
}

.note-meta {
  margin: 0.65rem 0 0;
  font-size: 0.8rem;
  color: var(--muted);
}

.feed-empty {
  margin: 0;
  padding: 1.5rem;
  text-align: center;
  color: var(--muted);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
}

