node -e '
const fs=require("fs");
const p="../runs/security-b.jsonl";
for (const l of fs.readFileSync(p,"utf8").trim().split("\n")) {
  const r=JSON.parse(l);
  if (r.type==="payload") console.log(r.id.padEnd(14), "fired="+r.fired, "jsLinks="+r.javascriptLinksRendered, "jsAvatar="+r.javascriptAvatarRendered, "dialogs="+r.dialogs, "csp="+JSON.stringify(r.csp), "errs="+JSON.stringify(r.pageErrors));
  else console.log(r.type, JSON.stringify(r).slice(0,300));
}'
